import fs from 'node:fs';import{gzipSync}from'node:zlib';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('clipaction_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const actions=['crop','duplicate-loop','duplicate-region','scrub-start','scrub-stop','move-playing-position'];
function setup(sim,kind){const clip=sim.state.tracks[0].clips[0];clip.loopStart=0.5;clip.loopEnd=3;if(kind.startsWith('audio')){clip.kind='audio';clip.isAudio=true;}if(kind.startsWith('arrangement')){sim.state.arrangementClips.push({trackRef:'track:track-1',clip:{...structuredClone(clip),ref:'arrangement-clip:track-1:0',objectIdentity:'simulator:arrangement-clip:0'}});}}
function params(kind){const action=kind.split(':')[1]??'crop';return{clipRef:kind.startsWith('arrangement')?'arrangement-clip:track-1:0':'clip:clip-1',action,...(action==='duplicate-region'?{regionStart:0.25,regionEnd:1.5,destination:4}:{}),...(['scrub-start','move-playing-position'].includes(action)?{offset:0.75}:{})};}
const rows=[];for(const kind of actions.map(a=>'session:'+a))for(const action of ['preview','apply']){const valid=action==='preview'?params(kind):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of action==='preview'?['clipRef','action','regionStart','regionEnd','destination','offset']:Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-4,-1,0,0.5,1,2,4,6,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,kind);const host=new McpHost(sim);rows.push({action,args,result:clean(await host[action==='preview'?'liveClipActionPreviewAsync':'liveClipActionApplyAsync'](1,args))});}}
const workflows=[];for(const kind of ['session','audio','arrangement'].flatMap(location=>actions.map(action=>`${location}:${action}`)))for(const scenario of ['normal','expire','epoch','identity-edit','source-content','loop-drift','playback-drift','is-playing-drift','hierarchy-drift','missing-loop','null-loop','empty-loop','backwards-loop','full-loop','inside-region','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-silent-no-effect','apply-read','apply-current-read','apply-preabort','apply-length-drift','apply-length-tolerance']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;const source=kind.startsWith('arrangement')?sim.state.arrangementClips[0].clip:sim.state.tracks[0].clips[0];if(scenario==='missing-identity')delete source.objectIdentity;if(scenario==='missing-loop'){delete source.loopStart;delete source.loopEnd;}if(scenario==='null-loop'){source.loopStart=null;source.loopEnd=null;}if(scenario==='empty-loop'){source.loopEnd=source.loopStart;}if(scenario==='backwards-loop')source.loopEnd=0;if(scenario==='full-loop'){source.loopStart=0;source.loopEnd=4;}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:fault==='apply-silent-no-effect'?{changed:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-length-drift','apply-length-tolerance'].includes(fault)){fired=true;source.length+=fault==='apply-length-drift'?0.01:0.0000001;}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args=params(kind);if(scenario==='inside-region'&&args.action==='duplicate-region')args.destination=0;const preview=await host.liveClipActionPreviewAsync(1,args);results.push(clean(preview));const body=preview.result?.content?.[0]?.text?JSON.parse(preview.result.content[0].text):{};const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveClipActionApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')source.objectIdentity='other';if(scenario==='source-content')source.name='Manual';if(scenario==='loop-drift')source.loopEnd=100;if(scenario==='playback-drift')source.playingPosition=2;if(scenario==='is-playing-drift')source.isPlaying=true;if(scenario==='hierarchy-drift')sim.state.tracks[0].objectIdentity='other';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-clip-action-oracle.json.gz',import.meta.url),gzipSync(JSON.stringify({rows,workflows}),{level:9}));console.log({rows:rows.length,workflows:workflows.length});
